INSERT INTO product_classifications(product_id,category_id,subcategory_id) SELECT id,CASE LOWER(TRIM(name)) WHEN 'ziemniaki' THEN 'vegetables' WHEN 'pomidory' THEN 'vegetables' WHEN 'ogórki' THEN 'vegetables' WHEN 'marchew' THEN 'vegetables' WHEN 'cebula' THEN 'vegetables' WHEN 'kapusta' THEN 'vegetables' WHEN 'jabłka' THEN 'fruit' WHEN 'gruszki' THEN 'fruit' WHEN 'śliwki' THEN 'fruit' WHEN 'truskawki' THEN 'fruit' WHEN 'maliny' THEN 'fruit' WHEN 'borówki' THEN 'fruit' WHEN 'mleko' THEN 'dairy' WHEN 'masło' THEN 'dairy' WHEN 'chleb' THEN 'bakery' WHEN 'miód lipowy' THEN 'honey' WHEN 'miód wielokwiatowy' THEN 'honey' WHEN 'miód gryczany' THEN 'honey' WHEN 'ziemniak' THEN 'vegetables' WHEN 'ziemniaki demonstracyjne' THEN 'vegetables' WHEN 'pomidor' THEN 'vegetables' WHEN 'ogórek' THEN 'vegetables' WHEN 'marchewka' THEN 'vegetables' WHEN 'marchew demonstracyjna' THEN 'vegetables' WHEN 'jabłko' THEN 'fruit' WHEN 'gruszka' THEN 'fruit' WHEN 'śliwka' THEN 'fruit' WHEN 'truskawka' THEN 'fruit' WHEN 'malina' THEN 'fruit' WHEN 'borówka' THEN 'fruit' WHEN 'miód rzepakowy' THEN 'honey' WHEN 'miód spadziowy' THEN 'honey' WHEN 'dżem' THEN 'preserves' WHEN 'dżemy' THEN 'preserves' WHEN 'konfitury' THEN 'preserves' WHEN 'kiszonki' THEN 'preserves' WHEN 'marynaty' THEN 'preserves' WHEN 'sosy' THEN 'preserves' WHEN 'ser' THEN 'dairy' WHEN 'sery' THEN 'dairy' WHEN 'twaróg' THEN 'dairy' WHEN 'twarogi' THEN 'dairy' WHEN 'jogurt' THEN 'dairy' WHEN 'jogurty' THEN 'dairy' WHEN 'wieprzowina' THEN 'meat' WHEN 'wołowina' THEN 'meat' WHEN 'drób' THEN 'meat' WHEN 'wędliny' THEN 'meat' WHEN 'jaja kurze' THEN 'eggs' WHEN 'jaja przepiórcze' THEN 'eggs' WHEN 'jaja kacze' THEN 'eggs' WHEN 'bułki' THEN 'bakery' WHEN 'ciasta' THEN 'bakery' WHEN 'ryby świeże' THEN 'fish' WHEN 'ryby wędzone' THEN 'fish' WHEN 'przetwory rybne' THEN 'fish' WHEN 'zboża' THEN 'grains' WHEN 'mąka' THEN 'grains' WHEN 'mąki' THEN 'grains' WHEN 'kasze' THEN 'grains' WHEN 'płatki owsiane' THEN 'grains' WHEN 'świeże zioła' THEN 'herbs' WHEN 'suszone zioła' THEN 'herbs' WHEN 'przyprawy' THEN 'herbs' WHEN 'grzyby świeże' THEN 'mushrooms' WHEN 'grzyby suszone' THEN 'mushrooms' WHEN 'przetwory grzybowe' THEN 'mushrooms' WHEN 'orzechy włoskie' THEN 'nuts-seeds' WHEN 'orzechy laskowe' THEN 'nuts-seeds' WHEN 'pestki dyni' THEN 'nuts-seeds' WHEN 'nasiona chia' THEN 'nuts-seeds' WHEN 'soki' THEN 'drinks' WHEN 'syropy' THEN 'drinks' WHEN 'napoje bezalkoholowe' THEN 'drinks' WHEN 'sadzonki warzyw' THEN 'plants' WHEN 'sadzonki owocowe' THEN 'plants' WHEN 'zioła w doniczkach' THEN 'plants' WHEN 'kwiaty' THEN 'plants' ELSE 'other' END,CASE LOWER(TRIM(name)) WHEN 'ziemniaki' THEN 'vegetables-potatoes' WHEN 'pomidory' THEN 'vegetables-tomatoes' WHEN 'ogórki' THEN 'vegetables-cucumbers' WHEN 'marchew' THEN 'vegetables-carrots' WHEN 'cebula' THEN 'vegetables-onions' WHEN 'kapusta' THEN 'vegetables-cabbage' WHEN 'jabłka' THEN 'fruit-apples' WHEN 'gruszki' THEN 'fruit-pears' WHEN 'śliwki' THEN 'fruit-plums' WHEN 'truskawki' THEN 'fruit-strawberries' WHEN 'maliny' THEN 'fruit-raspberries' WHEN 'borówki' THEN 'fruit-blueberries' WHEN 'mleko' THEN 'dairy-milk' WHEN 'masło' THEN 'dairy-butter' WHEN 'chleb' THEN 'bakery-bread' WHEN 'miód lipowy' THEN 'honey-linden' WHEN 'miód wielokwiatowy' THEN 'honey-multifloral' WHEN 'miód gryczany' THEN 'honey-buckwheat' WHEN 'ziemniak' THEN 'vegetables-potatoes' WHEN 'ziemniaki demonstracyjne' THEN 'vegetables-potatoes' WHEN 'pomidor' THEN 'vegetables-tomatoes' WHEN 'ogórek' THEN 'vegetables-cucumbers' WHEN 'marchewka' THEN 'vegetables-carrots' WHEN 'marchew demonstracyjna' THEN 'vegetables-carrots' WHEN 'jabłko' THEN 'fruit-apples' WHEN 'gruszka' THEN 'fruit-pears' WHEN 'śliwka' THEN 'fruit-plums' WHEN 'truskawka' THEN 'fruit-strawberries' WHEN 'malina' THEN 'fruit-raspberries' WHEN 'borówka' THEN 'fruit-blueberries' WHEN 'miód rzepakowy' THEN 'honey-rapeseed' WHEN 'miód spadziowy' THEN 'honey-honeydew' WHEN 'dżem' THEN 'preserves-jams' WHEN 'dżemy' THEN 'preserves-jams' WHEN 'konfitury' THEN 'preserves-confitures' WHEN 'kiszonki' THEN 'preserves-fermented' WHEN 'marynaty' THEN 'preserves-pickled' WHEN 'sosy' THEN 'preserves-sauces' WHEN 'ser' THEN 'dairy-cheese' WHEN 'sery' THEN 'dairy-cheese' WHEN 'twaróg' THEN 'dairy-curd' WHEN 'twarogi' THEN 'dairy-curd' WHEN 'jogurt' THEN 'dairy-yogurt' WHEN 'jogurty' THEN 'dairy-yogurt' WHEN 'wieprzowina' THEN 'meat-pork' WHEN 'wołowina' THEN 'meat-beef' WHEN 'drób' THEN 'meat-poultry' WHEN 'wędliny' THEN 'meat-sausages' WHEN 'jaja kurze' THEN 'eggs-chicken' WHEN 'jaja przepiórcze' THEN 'eggs-quail' WHEN 'jaja kacze' THEN 'eggs-duck' WHEN 'bułki' THEN 'bakery-rolls' WHEN 'ciasta' THEN 'bakery-cakes' WHEN 'ryby świeże' THEN 'fish-fresh' WHEN 'ryby wędzone' THEN 'fish-smoked' WHEN 'przetwory rybne' THEN 'fish-preserved' WHEN 'zboża' THEN 'grains-grains' WHEN 'mąka' THEN 'grains-flour' WHEN 'mąki' THEN 'grains-flour' WHEN 'kasze' THEN 'grains-groats' WHEN 'płatki owsiane' THEN 'grains-flakes' WHEN 'świeże zioła' THEN 'herbs-fresh' WHEN 'suszone zioła' THEN 'herbs-dried' WHEN 'przyprawy' THEN 'herbs-spices' WHEN 'grzyby świeże' THEN 'mushrooms-fresh' WHEN 'grzyby suszone' THEN 'mushrooms-dried' WHEN 'przetwory grzybowe' THEN 'mushrooms-preserved' WHEN 'orzechy włoskie' THEN 'nuts-seeds-nuts' WHEN 'orzechy laskowe' THEN 'nuts-seeds-nuts' WHEN 'pestki dyni' THEN 'nuts-seeds-kernels' WHEN 'nasiona chia' THEN 'nuts-seeds-seeds' WHEN 'soki' THEN 'drinks-juice' WHEN 'syropy' THEN 'drinks-syrup' WHEN 'napoje bezalkoholowe' THEN 'drinks-soft-drinks' WHEN 'sadzonki warzyw' THEN 'plants-vegetables' WHEN 'sadzonki owocowe' THEN 'plants-fruit' WHEN 'zioła w doniczkach' THEN 'plants-potted-herbs' WHEN 'kwiaty' THEN 'plants-flowers' ELSE 'other-other' END FROM products WHERE id NOT IN (SELECT product_id FROM product_classifications);
