-- Additive, conservative taxonomy backfill; never rewrite products or orders.
BEGIN;
CREATE TABLE IF NOT EXISTS product_categories(id TEXT PRIMARY KEY,label TEXT NOT NULL,position INTEGER NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS product_subcategories(id TEXT PRIMARY KEY,category_id TEXT NOT NULL REFERENCES product_categories(id),label TEXT NOT NULL,position INTEGER NOT NULL,UNIQUE(id,category_id));
CREATE TABLE IF NOT EXISTS product_classifications(product_id BIGINT PRIMARY KEY REFERENCES products(id),category_id TEXT NOT NULL REFERENCES product_categories(id),subcategory_id TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',FOREIGN KEY(subcategory_id,category_id) REFERENCES product_subcategories(id,category_id));
CREATE INDEX IF NOT EXISTS product_classification_category ON product_classifications(category_id,subcategory_id,product_id);
COMMIT;
